<?php
require __DIR__.'/config/database.php';
$id=(int)($_GET['id']??0);
$q=$pdo->prepare('SELECT o.*,c.business_name,c.address,c.phone FROM bonilla_orders o LEFT JOIN bonilla_clients c ON c.id=o.client_id WHERE o.id=?');$q->execute([$id]);$o=$q->fetch();
if(!$o){http_response_code(404);exit('Pedido no encontrado');}
$q=$pdo->prepare('SELECT * FROM bonilla_order_items WHERE order_id=?');$q->execute([$id]);$items=$q->fetchAll();
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function m($v){return number_format((float)$v,2,',','.').' €';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>Documento del pedido #<?=h($o['id'])?></title><style>body{font-family:Arial;color:#172033;max-width:850px;margin:35px auto;padding:20px}header{display:flex;justify-content:space-between;border-bottom:4px solid #d71920;padding-bottom:18px}img{width:220px;max-height:100px;object-fit:contain}.box{background:#f4f6f8;padding:18px;margin:22px 0;border-radius:10px}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}th{background:#172033;color:white}.total{text-align:right;font-size:22px;font-weight:bold;margin-top:20px}.firma{display:flex;gap:80px;margin-top:80px}.firma div{border-top:1px solid #555;width:40%;padding-top:10px}@media print{button{display:none}}</style></head><body><header><img src="assets/logo-zq.png"><div><h1>Documento del pedido</h1><b>N.º <?=h($o['id'])?></b><br><?=h($o['order_date'])?></div></header><div class="box"><b>Cliente:</b> <?=h($o['business_name'])?><br><?=h($o['address'])?><br><?=h($o['phone'])?></div><table><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>IVA</th><th>Importe</th></tr><?php foreach($items as $i):?><tr><td><?=h($i['product_name'])?></td><td><?=h($i['quantity'])?></td><td><?=m($i['unit_price'])?></td><td><?=h($i['vat'])?>%</td><td><?=m($i['quantity']*$i['unit_price'])?></td></tr><?php endforeach;?></table><div class="total">Subtotal: <?=m($o['subtotal'])?><br>Descuento: <?=m($o['discount']??0)?><br>IVA: <?=m($o['vat_total'])?><br>Total: <?=m($o['total'])?><br><span style="font-size:15px">Estado: <?=h(($o['payment_status']??'pendiente')==='cobrado'?'Cobrado':'Pendiente de cobro')?></span></div><div class="firma"><div>Firma del cliente</div><div>Firma representante</div></div><button onclick="window.print()">Imprimir / guardar PDF</button></body></html>
